import React from 'react'
import { useNavigate } from 'react-router-dom';

function Register() {
    const navigate = useNavigate();
    const [user, setUser] = useState({
        fullname: '',
        email: '',
        password: '',
        phone: ''
    });
    const { fullname, email, password, phone } = user;

    const onInputChange = async(e) => {
        setUser({ ...user, [e.target.name]: e.target.value });
    }

    const onSubmit = async(e) => {
        e.preventDefault();
        await axios.post("http://localhost:8080/user", user);
        alert("User registered successfully");
        window.location.reload();
    }

  return (
    <div>
      <h1>Register</h1>
      <form onSubmit={onSubmit}>
        <label htmlFor="fullname">fullname</label><br />
        <input type="text" id="fullname" name="fullname" value={fullname} onChange={onInputChange} required />
        <br />

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={email} onChange={onInputChange} required /><br />
        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={password} onChange={onInputChange} required /><br />

        <label htmlFor="phone">phone</label><br />
        <input type="text" id="phone" name="phone" value={phone} onChange={onInputChange} />
        <br />
        <button type="submit" className="fom_btn">register</button>
      </form>
    </div>
  )
}

export default Register
